layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(247, 247, 247); border-top: 1px solid rgb(237, 237, 237); border-right: 1px solid rgb(237, 237, 237); border-bottom: 1px solid rgb(237, 237, 237); border-left: 1px solid rgb(237, 237, 237); border-radius: 12px; box-shadow: rgb(237, 237, 237) 0px 1px 2px 0px; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: italic; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 9px; padding-right: 18px; padding-bottom: 9px; padding-left: 18px; transition: all }
article[data-ryt="rec-card"] { border-bottom: 1px dotted var(--ryt-border); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-border); border-bottom: 1px dotted var(--ryt-border); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-border); border-bottom: 1px dotted var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-muted); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-top: 1px solid rgb(237, 237, 237); border-bottom: none }
[data-ryt="nav"] a { color: var(--ryt-muted); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-border); border-bottom: 1px dotted var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"]:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor }
[data-ryt="nav"] a:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor; color: hsl(
    0 0% clamp(8%, calc(100% - 99%), 92%)
  ) }
[data-ryt="brand"]:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor }
[data-ryt="hero"] h1:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor }
article[data-ryt="rec-card"]:hover { border-bottom-width: 1px; border-bottom-style: solid; border-bottom-color: currentcolor }
